    let pathnameWithLeadingSlash = pathnameValue;
    if (!pathnameValue.startsWith('/')) {
      pathnameWithLeadingSlash = toVersionPathWithLeadingSlash(pathnameValue);
    }
    let pathnameWithTrailingSlash = pathnameValue;
    if (!pathnameValue.endsWith('/')) {
      pathnameWithTrailingSlash = toVersionPathWithTrailingSlash(pathnameValue);
    }
    let pathnameWithoutTrailingSlash = pathnameValue;
    if (pathnameValue !== '/' && pathnameValue.endsWith('/')) {
      pathnameWithoutTrailingSlash =
        toVersionPathWithoutTrailingSlash(pathnameValue);
