                path: versionPath,
                exact: false,
                strict: false,
              });
            }
          } else {
            matched = !!matchPath(pathname, {
              path: versionPath,
              exact: false,
              strict: false,
            });
          }
        } else {
          matched = !!matchPath(pathname, {
            path: versionPath,
            exact: false,
            strict: false,
          });
        }
      } else if (
        pathnameValue.startsWith(`${versionPathWithoutTrailingSlash}/`) ||
        pathnameValue.startsWith(versionPathWithTrailingSlash)
      ) {
        if (versionPathWithoutTrailingSlash === '/') {
          matched = !!matchPath(pathname, {
            path: versionPath,
            exact: false,
            strict: false,
          });
