                path: versionPath,
                exact: false,
                strict: false,
              });
            } else {
              matched = !!matchPath(pathname, {
                path: versionPath,
                exact: false,
                strict: false,
              });
            }
          } else {
            matched = !!matchPath(pathname, {
              path: versionPath,
              exact: false,
              strict: false,
            });
          }
        }
      } else {
        matched = !!matchPath(pathname, {
          path: versionPath,
          exact: false,
          strict: false,
        });
      }

      if (matched) {
        return version;
      }
    }

    return undefined;
  } catch (error) {
    if (error instanceof Error) {
      throw unwrapVersionPathError(error);
    }
    throw error;
  }
}

input.newString:
  // Sort by path length (descending) so that more specific paths are matched
  // first. The last version is usually a route like /docs/*, but the current
  // version can also use the root path /, which would match every route. We
  // cannot rely on the isLast attribute to order versions: the current version
  // path is configurable and may not be the "last" one.
  const orderedVersionsMetadata = [...data.versions].sort(
    (a, b) => b.path.length - a.path.length,
  );
  return orderedVersionsMetadata.find(
    (version) =>
      !!matchPath(pathname, {
        path: version.path,
        exact: false,
        strict: false,
      }),
  );
}

